SetQuitOnError(true);SetColumns(0);for ell in[3,5,7]do for d in[1..12]do q:=ell^d;if q+1+Floor(2*Sqrt(RealField(30)!q))lt 100000 then continue;end if;F:=GF(q);j:=ell eq 7 select F!1728 else F!0;ts:=Twists(EllipticCurveFromjInvariant(j));assert &and[IsSupersingular(E):E in ts];cs:=Sort(Setseq({#E:E in ts}));printf "S12_SS ell=%o d=%o orders=%o\n",ell,d,cs;end for;end for;print "S12_SS_ORDERS_COMPLETE";quit;
